import{_ as i,a0 as d,w as l,s as n,I as a,x as p,a1 as r,A as o,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"apt remove 和 apt purge: 有什麼區別？ | LCTT x X-CMD","titleTemplate":false,"description":"apt remove 和 apt purge: 有什麼區別？ | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"apt remove 和 apt purge: 有什麼區別？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"apt remove 和 apt purge: 有什麼區別？ | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221123.0 ⭐️⭐️ apt remove vs apt purge What’s the Difference","title":"apt remove 和 apt purge: 有什麼區別？","tag":"202301","desc":""},"relativePath":"202301/20221123.0 ⭐️⭐️ apt remove vs apt purge What’s the Difference.md","filePath":"[post].md"}'),m={name:"202301/20221123.0 ⭐️⭐️ apt remove vs apt purge What’s the Difference.md"};function g(u,e,f,c,h,v){const t=d("Link");return l(),n("div",null,[e[21]||(e[21]=a("h1",{id:"apt-remove-和-apt-purge-有什麼區別",tabindex:"-1"},[p("apt remove 和 apt purge: 有什麼區別？ "),a("a",{class:"header-anchor",href:"#apt-remove-和-apt-purge-有什麼區別","aria-label":"Permalink to “apt remove 和 apt purge: 有什麼區別？”"},"​")],-1)),e[22]||(e[22]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202301/19/113744ucqk6f69t4hbi8h8.jpg",alt:""})],-1)),a("p",null,[e[1]||(e[1]=p("如果你想 ",-1)),r(t,{href:"https://itsfoss.com/apt-remove/"},{default:o(()=>[...e[0]||(e[0]=[p("在 Ubuntu 上使用終端卸載軟件",-1)])]),_:1}),e[2]||(e[2]=p("，可以使用：",-1))]),e[23]||(e[23]=s('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove package_name</span></span></code></pre></div><p>但是在很多論壇，你可能會看到別人説，如果你想徹底刪除軟件就用 <code>apt purge</code>。</p><p>你可能會覺得很困惑，因為 <code>apt purge</code> 和 <code>apt remove</code> 看起來是一樣的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt purge package_name</span></span></code></pre></div><p>為什麼會有兩個如此像的命令來刪除軟件包呢？兩者之間有什麼不同呢？下面將為你揭曉。</p><h3 id="apt-remove-和-apt-purge-有什麼不同" tabindex="-1">apt-remove 和 apt-purge 有什麼不同？ <a class="header-anchor" href="#apt-remove-和-apt-purge-有什麼不同" aria-label="Permalink to “apt-remove 和 apt-purge 有什麼不同？”">​</a></h3><p><code>apt-remove</code> 和 <code>apt-purge</code> 的相同之處就是都可以卸載軟件包，但是運行 <code>apt-purge</code> 除了可以刪除安裝包之外，還可以清除相關的配置文件。這是兩者之間唯一的不同點。要注意的是這兩條命令都不能刪除用户主目錄中相關的應用程序文件。</p><p>你是否遇到過這樣的情況，卸載一個軟件然後重新安裝，卻發現之前的設置都還在。這是因為用 <code>apt remove</code> 不能刪除該軟件的相關配置文件。</p><h4 id="哪些東西被刪除了-哪些還在" tabindex="-1">哪些東西被刪除了？哪些還在？ <a class="header-anchor" href="#哪些東西被刪除了-哪些還在" aria-label="Permalink to “哪些東西被刪除了？哪些還在？”">​</a></h4><p>我分享一個使用 <code>apt remove</code> 和 <code>apt purge</code> 兩個命令分別卸載 mplayer 這個軟件的實際例子。重點是看每次操作後還殘餘哪些文件。</p><p>這是刪除前的文件：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/mplayer-before-removal.png" alt="mplayer before removal"></p><p>現在運行 <code>apt remove</code> 這個命令：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/apt-uninstall-package-ubuntu.png" alt="apt uninstall package ubuntu"></p><p>下面的是還殘留在系統中的文件：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/files-after-mplayer-removal.png" alt="files after mplayer removal"></p><p>我們可以看到，有兩個地方殘留着 mplayer 的文件: <code>/etc</code> 和 <code>/home/abhishek</code>。</p><p>這次我們重新安裝 mplayer，然後用 <code>apt purge</code> 來卸載軟件。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/apt-purge-command.png" alt="apt purge command"></p><p>現在讓我們看看與 mplayer 相關的文件：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/files-after-apt-purge.png" alt="files after mplayer removal"></p><p>我們可以看到 <code>/etc</code> 目錄下的文件已經沒有了。</p><p>但是在主目錄中的文件呢？<code>apt purge</code> 會刪除它們嗎？</p><p>答案是否定的。<code>apt</code> 命令不會刪除主目錄中的配置文件。所以它們仍然在系統中，除非你手動刪除。但是這些文件所佔的空間真的很小，幾乎不佔磁盤空間。</p><p>值得注意的是，不是所有的軟件在主目錄或者 <code>/etc</code> 目錄下都有配置文件。</p><h4 id="使用-apt-remove-或者-apt-purge-的效果" tabindex="-1">使用 apt remove 或者 apt purge 的效果 <a class="header-anchor" href="#使用-apt-remove-或者-apt-purge-的效果" aria-label="Permalink to “使用 apt remove 或者 apt purge 的效果”">​</a></h4>',26)),a("p",null,[e[4]||(e[4]=p("我能想到的一個實際例子就是 Discord，你用 deb 文件 ",-1)),r(t,{href:"https://itsfoss.com/install-discord-linux/"},{default:o(()=>[...e[3]||(e[3]=[p("在 Ubuntu 上安裝了 Discord",-1)])]),_:1}),e[5]||(e[5]=p("。然後登錄自己的賬號，之後又卸載並重新用 deb 文件安裝。",-1))]),e[24]||(e[24]=s('<p>現在如果你打開 Discord，你會發現你的賬號自動登錄了。是不是覺得很奇怪？</p><p>這是個功能，像一些軟件，比如 Discord、VirtualBox，它們會提供更新，就是卸載現在的版本然後下載新的（儘管你不知道它內部怎麼進行的），但是它在卸載的時候，這些軟件的配置文件沒有被刪除，所以等你打開這些軟件的時候就會自動登錄。</p><p>當你想卸載一個軟件，但是想保留你過去使用該軟件留下的配置文件的時候，你就可以用 <code>apt remove</code>。</p><p>但是，有時候用它不能滿足你的需求，比如當你沒有配置好一個軟件的時候，你想要重新開始，這個時候用 <code>apt purge</code> 就比較合適。</p><h4 id="運行-apt-purge-是否可以用通配符刪除" tabindex="-1">運行 apt purge 是否可以用通配符刪除？ <a class="header-anchor" href="#運行-apt-purge-是否可以用通配符刪除" aria-label="Permalink to “運行 apt purge 是否可以用通配符刪除？”">​</a></h4><p>當你刪除一個包的時候，它會提示 <code>removing package-name*</code>。這意味着它會刪除以這個包名開頭的所有文件。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/apt-purge-wild-card.png" alt="apt purge wild card"></p><p>我在手冊頁之類的文檔中沒有找到關於這個問題的答案。所以我自己做了一個小測試，我安裝了 espeak 和 espeak-ng 這兩個軟件，espeak* 應該可以通配擴展到 espeak-ng。</p><p>但是當我用 <code>apt purge</code> 刪除 espeak 包時，espeak-ng 包還在，沒有被一併刪除。因此，這似乎是有一種防止通配符的擴展的機制。</p><h3 id="那麼-你應該使用-apt-remove-還是-apt-purge-呢" tabindex="-1">那麼，你應該使用 apt remove 還是 apt purge 呢？ <a class="header-anchor" href="#那麼-你應該使用-apt-remove-還是-apt-purge-呢" aria-label="Permalink to “那麼，你應該使用 apt remove 還是 apt purge 呢？”">​</a></h3><p>很少有人會一直使用 <code>apt purge</code>。</p><p>在我看來，一般清況下，用 <code>apt remove</code> 就可以了，但是當你想刪除那些自定義配置文件時，你就得用 <code>apt purge</code>。</p><p>不管是用 <code>apt remove</code> 還是 <code>apt purge</code>，你都需要從用户的主目錄中刪除殘餘的配置文件，並運行 <code>apt autoremove</code> 來清除任何依賴的包。</p><p>現在到你啦。你現在對 <code>apt remove</code> 和 <code>apt purge</code> 的區別更加了解嗎？你更喜歡使用哪一個呢？</p><hr>',15)),a("p",null,[e[7]||(e[7]=p("via: ",-1)),r(t,{href:"https://itsfoss.com/apt-remove/"},{default:o(()=>[...e[6]||(e[6]=[p("https://itsfoss.com/apt-remove/",-1)])]),_:1})]),a("p",null,[e[12]||(e[12]=p("作者：",-1)),r(t,{href:"https://itsfoss.com/"},{default:o(()=>[...e[8]||(e[8]=[p("Abhishek Prakash",-1)])]),_:1}),e[13]||(e[13]=p(" 選題：",-1)),r(t,{href:"https://github.com/lkxed"},{default:o(()=>[...e[9]||(e[9]=[p("lkxed",-1)])]),_:1}),e[14]||(e[14]=p(" 譯者：",-1)),r(t,{href:"https://github.com/Tingze-G"},{default:o(()=>[...e[10]||(e[10]=[p("Tingze-G",-1)])]),_:1}),e[15]||(e[15]=p(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[11]||(e[11]=[p("wxy",-1)])]),_:1})]),a("p",null,[e[18]||(e[18]=p("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[16]||(e[16]=[p("LCTT",-1)])]),_:1}),e[19]||(e[19]=p(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:o(()=>[...e[17]||(e[17]=[p("Linux中國",-1)])]),_:1}),e[20]||(e[20]=p(" 榮譽推出",-1))])])}const x=i(m,[["render",g]]);export{T as __pageData,x as default};
